__load("series",{"s":[{"id":"dm","y":2000,"p":"Yugi Muto","w":"Yugi Muto","e":"","m":{"es":"Duelos clásicos: monstruos Normales, de Efecto, de Fusión y de Ritual, y las tres cartas de Dios Egipcio.","en":"Classic duels: Normal, Effect, Fusion and Ritual monsters, and the three Egyptian God cards."},"b":{"es":"La primera serie del anime centrada en el juego de cartas, basada en el manga de Kazuki Takahashi. Sigue a Yugi y su Rompecabezas del Milenio por torneos como Duelist Kingdom y Battle City, y definió cómo se jugaba en los primeros años del TCG.","en":"The first anime series centered on the card game, based on Kazuki Takahashi's manga. It follows Yugi and his Millennium Puzzle through tournaments such as Duelist Kingdom and Battle City, and it shaped how the game was played in the early years of the TCG."}},{"id":"gx","y":2004,"p":"Jaden Yuki","w":"Jaden Yuki","e":"goat","m":{"es":"Fusión con los Elemental HERO y las cartas Neo-Espaciales, en una escuela de duelistas.","en":"Fusion with Elemental HERO and Neo-Spacian cards, set in a school for duelists."},"b":{"es":"La primera serie derivada. Jaden Yuki estudia en la Academia de Duelo, y sus Elemental HERO hicieron famosa la Invocación por Fusión. El formato retro Goat es de esta época del juego.","en":"The first spin-off series. Jaden Yuki studies at Duel Academy, and his Elemental HEROes made Fusion Summoning famous. The Goat retro format comes from this era of the game."}},{"id":"5d","y":2008,"p":"Yusei Fudo","w":"Yusei Fudo","e":"edison","m":{"es":"Invocación Sincro y Duelos Turbo sobre motos llamadas Duel Runners.","en":"Synchro Summoning and Turbo Duels on motorcycles called Duel Runners."},"b":{"es":"Yusei Fudo y sus amigos se enfrentan en duelos en un mundo dividido entre la ciudad y los suburbios. Esta serie trajo la Invocación Sincro. El formato retro Edison es de esta época.","en":"Yusei Fudo and his friends duel in a world split between the city and the satellite slums. This series brought Synchro Summoning. The Edison retro format comes from this era."}},{"id":"zx","y":2011,"p":"Yuma Tsukumo","w":"Yuma Tsukumo","e":"","m":{"es":"Invocación Xyz y las cartas Number.","en":"Xyz Summoning and the Number cards."},"b":{"es":"Yuma Tsukumo y su compañero Astral buscan las cartas Number. Esta serie trajo la Invocación Xyz, que apila monstruos del mismo Nivel. Es la tercera serie derivada del anime, después de GX y 5D's.","en":"Yuma Tsukumo and his partner Astral hunt for the Number cards. This series brought Xyz Summoning, which stacks monsters of the same Level. It is the third spin-off series, after GX and 5D's."}},{"id":"av","y":2014,"p":"Yuya Sakaki","w":"Yuya Sakaki","e":"","m":{"es":"Invocación de Péndulo, con cuatro dimensiones que usan cada una un tipo de invocación distinto.","en":"Pendulum Summoning, with four dimensions that each use a different kind of summon."},"b":{"es":"La cuarta serie derivada principal. Yuya Sakaki y Zuzu Boyle viajan entre dimensiones paralelas. Esta serie trajo la Invocación de Péndulo, con cartas que son monstruo y Magia a la vez.","en":"The fourth main spin-off series. Yuya Sakaki and Zuzu Boyle travel between parallel dimensions. This series brought Pendulum Summoning, with cards that are both a monster and a Spell."}},{"id":"vr","y":2017,"p":"Playmaker","w":"Yusaku Fujiki (Playmaker)","e":"","m":{"es":"Invocación Link y el mundo virtual llamado Link VRAINS.","en":"Link Summoning and the virtual world called Link VRAINS."},"b":{"es":"Yusaku Fujiki, que compite como Playmaker, se mueve por la red virtual de Link VRAINS. Esta serie trajo la Invocación Link, que apunta con flechas a otras zonas del campo.","en":"Yusaku Fujiki, who duels as Playmaker, moves through the virtual network of Link VRAINS. This series brought Link Summoning, which points with arrows at other zones of the field."}}],"l":{"Jaden Yuki":"jaden-yuki","Joey Wheeler":"joey-wheeler","Marik Ishtar":"marik-ishtar","Seto Kaiba":"seto-kaiba","Yubel":"yubel","Yugi Muto":"yugi-muto","Yusei Fudo":"yusei-fudo"}});